    auto& style=ImGui::GetStyle();style.WindowRounding=3;style.FrameRounding=3;style.Colors[ImGuiCol_WindowBg]={.045f,.065f,.085f,1};style.Colors[ImGuiCol_Header]={.09f,.22f,.32f,1};style.Colors[ImGuiCol_Button]={.08f,.18f,.25f,1};
    if(ImGui::BeginMainMenuBar()){ImGui::TextColored({.25f,.75f,.95f,1},"DarkAngel");ImGui::Separator();if(ImGui::BeginMenu("File")){if(ImGui::MenuItem("New Scene"))action(editor,[&]{editor.demo();});if(ImGui::MenuItem("Open..."))action(editor,[&]{auto path=dialog(false);if(!path.empty())editor.open(path);});if(ImGui::MenuItem("Save Scene"))action(editor,[&]{editor.save(editor.path);});if(ImGui::MenuItem("Save As..."))action(editor,[&]{auto path=dialog(true);if(!path.empty())editor.save(path);});ImGui::EndMenu();}ImGui::SameLine();ImGui::Text("%s | %s",backend,editor.preview.active()?(editor.paused?"Paused":"Playing"):"Stopped");ImGui::EndMainMenuBar();}
