    if(show_script){ImGui::Begin("Spinner Script",&show_script);ImGui::InputTextMultiline("##source",script,sizeof(script),{-1,300});if(ImGui::Button("Apply source"))action(editor,[&]{auto asset=AssetId::parse("33333333-3333-4333-8333-333333333333");auto source=nlohmann::json::parse(editor.document->source(asset));source["source"]=script;auto transaction=editor.document->prepare_source(editor.document->revision(),asset,source.dump());editor.document->commit(transaction);editor.log("Source saved in authoring memory. Reload Scripts validates/activates it.");});ImGui::End();}
